unsigned short COM1_PORT = 0x3F8;
unsigned int CONFIG_VALUE = 0xDEADBEEF;

// Grant I/O access (e.g., 4 bytes starting at port 0x3F8)
// Needs CAP_SYS_RAWIO capability
ioperm(COM1_PORT, 4, 1);

// Write 32-bit value and wait for completion
outl_p(CONFIG_VALUE, COM1_PORT);

// Optionally revoke access
ioperm(COM1_PORT, 4, 0);

// Alternative high privilege setup:
// iopl(3); // Sets CPL to 0 for all I/O
// outl_p(0x12345678, 0x1000);
